export function createCommandMap(): Record<string, ICommand> {
  const map: Record<string, ICommand> = {};
  for (const [commandName, spec] of Object.entries(specs)) {
    const { ...rest } = spec;
    map[commandName] = { commandName, ...rest } as ICommand;
  }
  // The default command map is public API; users can add or replace entries.
  return map;
}

export { specs as builtinCommandSpecs };

